CREATE TABLE naturalConsolidationMeta(version INTEGER PRIMARY KEY CHECK(version=1),schemaHash TEXT NOT NULL);
CREATE TABLE naturalMemoryCoverage(sourceKey TEXT PRIMARY KEY,turnSequence INTEGER NOT NULL UNIQUE REFERENCES projectMemoryTurns(sequence),projectId TEXT NOT NULL,sessionId TEXT NOT NULL,messageId TEXT NOT NULL,sourceHash TEXT NOT NULL,stage TEXT NOT NULL CHECK(stage IN ('captured','processed','deferred','withdrawn')),reason TEXT NOT NULL DEFAULT '',updatedAt TEXT NOT NULL);
CREATE TABLE naturalMemoryBatches(id TEXT PRIMARY KEY,projectId TEXT NOT NULL,sessionId TEXT NOT NULL,createdAt TEXT NOT NULL);
CREATE TABLE naturalMemoryBatchMembers(batchId TEXT NOT NULL REFERENCES naturalMemoryBatches(id),jobId TEXT NOT NULL,sourceKey TEXT NOT NULL,PRIMARY KEY(batchId,jobId));
CREATE TABLE naturalMemoryRelations(changeId TEXT PRIMARY KEY REFERENCES naturalPreferenceChanges(id),relation TEXT NOT NULL CHECK(relation IN ('new','equivalent','correction')),batchId TEXT NOT NULL REFERENCES naturalMemoryBatches(id));
CREATE TABLE naturalPreferenceSupports(entryId TEXT NOT NULL,revision INTEGER NOT NULL,sourceProject TEXT NOT NULL,sourceSession TEXT NOT NULL,sourceMessage TEXT NOT NULL,sourceHash TEXT NOT NULL,quoteRevision INTEGER NOT NULL,PRIMARY KEY(entryId,revision,sourceMessage,sourceHash),FOREIGN KEY(entryId,revision) REFERENCES naturalPreferenceRevisions(entryId,revision));
CREATE TABLE naturalPreferenceConflicts(id TEXT PRIMARY KEY,scopeKey TEXT NOT NULL,entryId TEXT NOT NULL REFERENCES naturalPreferenceEntries(id),expectedRevision INTEGER NOT NULL,sourceProject TEXT NOT NULL,sourceSession TEXT NOT NULL,sourceMessage TEXT NOT NULL,sourceHash TEXT NOT NULL,quoteHash TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','rejected','superseded','withdrawn')),createdAt TEXT NOT NULL,resolvedAt TEXT NOT NULL DEFAULT '',UNIQUE(entryId,sourceMessage,sourceHash));
CREATE TABLE naturalPreferenceConflictContent(id TEXT PRIMARY KEY REFERENCES naturalPreferenceConflicts(id),body TEXT NOT NULL);
CREATE INDEX naturalMemoryCoverage_stage ON naturalMemoryCoverage(stage,projectId,turnSequence);
CREATE INDEX naturalPreferenceConflicts_entry ON naturalPreferenceConflicts(entryId,status);
